def integral(bins, edges):
  if len(bins) > len(edges):
    raise ValueError("edges must equal or exceed the number of bins")

  integral = 0
  for i in range(len(bins)):
    bin_min = edges[i]
    bin_max = edges[i+1]
    bin_width = bin_max - bin_min
    integral += bins[i] * bin_width

  return integral

