        if isinstance(params, dict):
            params = params.items()
        # If the params are a list or tuple, then use the corresponding index for the out-style parameters
        elif isinstance(params, (list, tuple)):
            params = enumerate(params)
        # If the params are something else, then raise a TypeError
        else:
            raise TypeError("params must be a Mapping or Sequence")

