        out_style_param = {}

        # Iterate over each (key, value) pair in the set of in-style parameters
        for key, value in params:
            # If the key is a string, then use it as the key for the out-style parameter
            if isinstance(key, str):
                out_style_param[key] = value
            # If the key is an int, then use the corresponding ordinal index for the out-style parameter
            elif isinstance(key, int):
                out_style_param[str(key + 1)] = value
            # If the key is something else, then raise a TypeError
            else:
                raise TypeError("key must be a string or int")

        # Add the converted out-style parameters to the list
        out_style_params.append(out_style_param)

