    return sql, out_style_params

def formatmany(self, sql, many_params):
    # Initialize an empty list to store the converted out-style parameters
    params = []

    # Iterate over each set of in-style parameters
    for params in many_params:
        # If the parameters are in named style, convert them to out-style
        if isinstance(params, dict):
            params = {str(key): value for key, value in params.items()}
        # If the parameters are in ordinal style, convert them to out-style
        elif isinstance(params, Sequence):
            params = [value for value in params]

        # Append the converted parameters to the list
        params.append(params)

    # Join the converted parameters with commas
    params = ",".join(params)

    # Replace the placeholders in the SQL query with the converted parameters
    sql = sql.format(*params)

    # Return the formatted SQL query and the converted out-style parameters
    return (sql, params)

