        return '[\n' + ''.join(f'  {x.pretty(indent + 1, debug)}' for x in self) + '\n]\n'
    elif isinstance(self, dict):
        return '{\n' + ''.join(f'  {key}: {value.pretty(indent + 1, debug)}' for key, value in self.items()) + '\n}\n'
    elif isinstance(self, bool):
        return f'Bool: {self}'
    elif isinstance(self, int):
        return f'Int: {self}'
    elif isinstance(self, float):
        return f'Float: {self}'
    elif isinstance(self, complex):
        return f'Complex: {self}'
    elif isinstance(self, NoneType):
        return 'None'
    else:
        raise TypeError(f'Unsupported type {type(self)}')

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    lines = []
    for attribute, value in self.__dict__.items():
        lines.append(f"{attribute}:\n")
        if isinstance(value, list):
            for item in value:
                lines.append(f"  {pretty(item, indent=indent+2, debug=debug)}\n")
        elif isinstance(value, dict):
            for key, val in value.items():
                lines.append(f"  {key}: {pretty(val, indent=indent+2, debug=debug)}\n")
        else:
            lines.append(f" {value}\n")
    return "".join(lines)

