    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    return [absorb_expr(arg) for arg in args]

def absorb_expr(expr):
    if isinstance(expr, And) and any(isinstance(arg, Or) for arg in expr.args):
        return absorb_expr(And(*[arg for arg in expr.args if not isinstance(arg, Or)]))
    elif isinstance(expr, Or) and any(isinstance(arg, And) for arg in expr.args):
        return absorb_expr(Or(*[arg for arg in expr.args if not isinstance(arg, And)]))
    elif isinstance(expr, And) and len(expr.args) == 2 and expr.args[0] == expr.args[1]:
        return expr.args[0]
    elif isinstance(expr, Or) and len(expr.args) == 2 and expr.args[0] == expr.args[1]:
        return expr.args[0]
    elif isinstance(expr, And) and all(isinstance(arg, Not) for arg in expr.args):
        return Or(*[arg.arg for arg in expr.args])
    elif isinstance(expr, Or) and any(isinstance(arg, Not) for arg in expr.args):
        return And(*[arg.arg for arg in expr.args])
    else:
        return expr

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.name == "&" or arg.name == "|":
            if arg.args[0].name == arg.name:
                new_args.append(arg.args[0])
            elif arg.args[1].name == arg.name:
                new_args.append(arg.args[1])
            else:
                new_args.append(arg)
        elif arg.name == "~":
            if arg.args[0].name == "~":
                new_args.append(arg.args[0].args[0].args[0])
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

