def absorb_expression(self, arg):
    """
    Given an `arg` expression, return a new expression applying absorption and negative absorption.
    """
    if isinstance(arg, And):
        lhs, rhs = arg.args
        return self.absorb_expression(lhs) & self.absorb_expression(rhs)
    elif isinstance(arg, Or):
        lhs, rhs = arg.args
        return self.absorb_expression(lhs) | self.absorb_expression(rhs)
    elif isinstance(arg, Not):
        expr = arg.args[0]
        return ~self.absorb_expression(expr)
    else:
