def render_pieces(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces or not style:
        return None
    tab_width = max(len(piece) for piece in pieces)
    style_width = len(style)
    rendered = []
    for piece in pieces:
        if style_width == 0:
            break
        rendered.append(style[0] * (tab_width - len(piece)))
