def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for node_key, node_value in nodes:
        if node_key not in seen_keys:
            result.append((node_key, node_value))
            seen_keys.add(node_key)
        else:
            for idx, (key, value) in enumerate(result):
                if node_key == key:
                    new_value = deep_merge_nodes([(key, value), (node_key, node_value)])
                    result[idx] = (key, new_value)
                    break
    return result

def deep_merge_nodes(nodes):
    flattened_nodes = []
    mappings = []
    non_mappings = []

    for node_list in nodes:
        key, value = node_list
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            mappings.append((key, value))
        else:
            non_mappings.append((key, value))

    for mapping in mappings:
        key, mapping_value = mapping
        for mapping_key, mapping_value in mapping_value.value:
            if isinstance(mapping_value, ruamel.yaml.nodes.MappingNode):
                flattened_nodes.append((mapping_key, mapping_value))
            else:
                flattened_nodes.append((mapping_key, mapping_value))

    merging_result = []
    for node in non_mappings + flattened_nodes:
        if node not in merging_result:
            merging_result.append(node)

    return merging_result

