def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    # Import the required modules
    from borgmatic import main
    from borgmatic.cli import load_commands, load_context

    # Load the command parsers
    context = load_context()
    commands = load_commands(context)

    # Build the completion script
    script = []
    for _, command in commands.items():
        for param in command.params:
            if param.param_type_name == "option":
                option = max(param.opts, key=len)
                same_dest = [
                    max(p.opts, key=len) for p in command.params if p.name == param.name
                ]
                if same_dest:
                    option = "({})".format(" ".join(same_dest)) + option
                if param.help:
                    option += "[{}]".format(param.help or "")
                if not param.is_flag:
                    option += "=:( )"
                script.append(option)
            elif param.param_type_name == "argument":
                option = max(param.opts, key=len)
                script.append(":{}".format(option))

    # Print the completion script
    return "\n".join(script)

