def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    if not size:
        return 0

    size = size.strip().lower()
    if not size:
        return 0

    units = ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']
    num_units = len(units)
    power_1000 = 0
    num = 0
    for i, u in enumerate(units):
        if u and size.endswith(u):
            power_1000 = i
            num = size[:-1]
            break
    num = float(num)

    if power_1000 == 0:
        return int(num)
    elif power_1000 < num_units - 1:
        return int(num * (1000 ** power_1000))
    else:
        # estimation using 1,024-based units
        return int(num * (1024 ** (power_1000 - num_units)))

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size (str): A string representing a human readable file size (eg: '500K')

    Returns:
        int: A decimal representation of file size
    """
    size = size.upper()
    units = {'B': 1, 'K': 1000, 'M': 1000000, 'G': 1000000000}
    if size[-1] not in units:
        raise ValueError(f"Invalid file size: '{size}'. Must end with K, M, or G.")
    return int(float(size[:-1]) * units[size[-1]])

