    # Check if commands are valid
    if not isinstance(commands, (list, tuple)):
        raise TypeError("Expected a list or tuple of command and arguments")
    # Build the command
    cmd = [str(command) for command in commands]
    if args is not None:
        if not isinstance(args, (list, tuple)):
            raise TypeError("Expected a list or tuple of arguments")
        cmd.extend(args)
    # Run the command
    result = subprocess.run(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    # Check if the command failed
    if result.returncode != 0:
        raise subprocess.CalledProcessError(result.returncode, cmd)
    # Output the result
