    for value in values:
        bookmark = {}
        split_value = value.split()
        bookmark["id"] = split_value.pop(0)
        bookmark["title"] = split_value.pop(0)
        bookmark["url"] = " ".join(split_value)
        bookmarks.append(bookmark)
    return cls(bookmarks)

