def _get_seq_with_type(seq, bufsize=None):
    if isinstance(seq, str):
        return (seq, 'string')
    elif isinstance(seq, bytes):
        return (seq, 'bytes')
    elif isinstance(seq, bytearray):
        return (seq, 'bytearray')
    elif isinstance(seq, memoryview):
        return (seq, 'memoryview')
    elif isinstance(seq, (list, tuple)):
        return (seq, 'list/tuple')
    else:
        raise TypeError('Expected string, bytes, list or tuple, got {}'.format(type(seq).__name__))

def scale(self, other=None, recompute=False):
    if other is None:
        if self._scale is None or recompute:
            self._scale = self.compute_scale()
        return self._scale
    elif isinstance(other, float):
        if self._scale is None:
            raise LenaValueError("Histograms with scale equal to zero can't be rescaled")
        factor = other / self.scale
        self.histogram *= factor
        self._scale *= factor
        return self._scale
    else:
        raise TypeError("other must be either None or a number")

def scale(self, other=None):
    if other is None:
        return self._scale
    if other <= 0:
        raise ValueError("The scale must be a positive value.")

    scale_changed = other != self._scale
    self._scale = other

    if scale_changed:
        self._update_position()
        self._update_orientation()
        self._update_errors()
        self._update_label()

    return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
      g = Graph(dim=hist.dim)
      if field_names is not None and len(field_names) != g.dim:
          raise ValueError("Field names and graph dimension mismatch")
      if scale is None:
          g.scale = hist.scale
      elif scale is not True:
          g.scale = scale
      for bin in hist.bins:
          if not isinstance(bin, numbers.Number):
              if make_value is None:
                  raise TypeError("Cannot infer value of graph point")
              coord = _get_graph_coordinate(get_coordinate, bin)
              value = make_value(bin)
              if not isinstance(value, tuple):
                  value = (bin, value)
              g.add_point(coord, value)
      if field_names:
          g.field_names = field_names
      return g

def _get_graph_coordinate(get_coordinate, bin):
      if get_coordinate == "left":
          return bin.left
      if get_coordinate == "right":
          return bin.right
      if get_coordinate == "middle":
          return bin.left + (bin.right - bin.left)/2
      raise ValueError("Unknown coordinate: " + get_coordinate)

def _get_attribute_dimension(name: str, cls) -> int:
    """
    Return dimension of an attribute.
    """
    if not hasattr(cls, name):
        raise ValueError(f"Class {cls} has no attribute {name}")
    dim = getattr(cls, name).dim
    return dim

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    graph = Graph(scale=scale)
    if make_value is None:
        make_value = lambda bin: bin.content
    coordinate_funcs = {
        "left": lambda bin: bin.range[0],
        "middle": lambda bin: (bin.range[0] + bin.range[1]) / 2,
        "right": lambda bin: bin.range[1],
    }
    coordinate_func = coordinate_funcs[get_coordinate]
    for bin in hist:
        value = make_value(bin)
        point = coordinate_func(bin)
        graph.add_point(point, value, *field_names)
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    graph = Graph(scale=scale if scale else hist.scale)
    bin_width = hist.bin_width
    for i, bin_ in enumerate(hist.bins):
        if make_value is None:
            point_value = bin_
        else:
            point_value = make_value(bin_)
        point = GraphPoint(point_value)
        point.x = bin_.center
        if get_coordinate == "right":
            point.x += bin_width / 2
        elif get_coordinate == "middle":
            point.x += bin_width / 2
        graph.points[i] = point
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if isinstance(hist, Hist):
        bins = hist.bins
    else:
        bins = hist
    if make_value is None:
        make_value = lambda x: x
    if get_coordinate == "left":
        get_coordinate = lambda i: bins[:-1][i]
    if get_coordinate == "right":
        get_coordinate = lambda i: bins[1:][i]
    if get_coordinate == "middle":
        get_coordinate = lambda i: (bins[:-1][i] + bins[1:][i]) / 2
    x = [get_coordinate(i) for i in range(len(bins) - 1)]
    y = [make_value(bins[i]) for i in range(len(bins) - 1)]
    return Graph(x, y, field_names=field_names, scale=scale)

def _verify(iface, candidate, tentative=False, vtype=None):
    # First, check if the candidate class either directly or indirectly provides the interface
    if not (iface.directlyProvidedBy(candidate) or iface.providedBy(candidate)):
        return False

    # Next, check if the candidate defines all the necessary methods
    for name in iface.names(removed=False):
        if name not in candidate:
            return False

    # Finally, check if the methods have the correct signature
    for name in iface.names(removed=False):
        iface_method = getattr(iface, name)
        candidate_method = getattr(candidate, name)
        if not _verify_method_signature(iface_method, candidate_method):
            return False

    return True

def _verify_method_signature(iface_method, candidate_method):
    # Check if the method name and return type are the same
    if iface_method.__name__ != candidate_method.__name__ or iface_method.getReturnType() != candidate_method.getReturnType():
        return False

    # Check if the parameters are the same
    if len(iface_method.getParameters()) != len(candidate_method.getParameters()):
        return False
    for iface_param, candidate_param in zip(iface_method.getParameters(), candidate_method.getParameters()):
        if iface_param.getName() != candidate_param.getName() or iface_param.getType() != candidate_param.getType():
            return False

    return True

def verifyClass(iface, candidate, tentative=False):
    if not isinstance(candidate, iface):
        return False
    for method in iface.public_methods:
        try:
            candidate_method = getattr(candidate, method.__name__)
        except AttributeError:
            return False
        if not method is candidate_method:
            return False
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        iface_name = iface.__name__
        candidate_name = candidate.__name__
        if not iface_name.startswith("I"):
            raise InvalidInterfaceError(
                "Interface name '%s' does not start with 'I'" % iface_name
            )
        if not candidate_name.startswith("C"):
            raise InvalidCandidateError(
                "Candidate name '%s' does not start with 'C'" % candidate_name
            )
        checker = CandidateChecker(iface, candidate)
        if tentative:
            return checker.tentative_satisfied()
        else:
            return checker.satisfied()
    except Exception as e:
        raise VerifyClassFailedError(
            "VerifyClass failed with exception: %s" % str(e)
        ) from e

class CandidateChecker:
    def __init__(self, iface, candidate):
        self.iface = iface
        self.candidate = candidate

    def satisfied(self):
        iface_attrs = self.iface.__dict__.values()
        candidate_attrs = self.candidate.__dict__.values()
        return all(
            getattr(self.candidate, attr_name) == attr_value
            for attr_name, attr_value in iface_attrs.items()
            if attr_name in candidate_attrs
        )

    def tentative_satisfied(self):
        iface_attrs = self.iface.__dict__.values()
        candidate_attrs = self.candidate.__dict__.values()
        return all(
            getattr(self.candidate, attr_name, object()) == attr_value
            for attr_name, attr_value in iface_attrs.items()
            if attr_name in candidate_attrs
        )

