def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if iface is None or candidate is None:
        raise ValueError("iface and candidate must be non-null")
    if iface == object:
        return True
    if tentative:
        return issubclass(candidate, iface)
    else:
        return issubclass(candidate, iface) and hasattr(candidate, "__implementedBy__") and candidate.__implementedBy__ == iface

