        return isinstance(candidate, iface)

def determine_metaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If there are explicit bases, check them for __metaclass__ attribute
    if explicit_mc:
        try:
            for mc in explicit_mc:
                ctx = infer(mc)
                if ctx is not None:
                    return ctx
        except InferenceError:
            pass

    # If there are no explicit bases or inference failed, try checking implicit bases
    try:
        # Get the implicit metaclass for each base in bases
        implicit_mcs = [b.implicit_metaclass() for b in bases]

        # Iterate over each implicit metaclass and check if it has the desired __metaclass__ attribute
        for mc in implicit_mcs:
            ctx = infer(mc)
            if ctx is not None:
                return ctx
    except InferenceError:
        pass

    # If no metaclass could be determined, return None
    return None

def implicit_metaclass(self):
    """Check if type_ is subclassable."""
    try:
        class _(type_):  # type: ignore
            """Check if type_ is subclassable."""

        BaseClass = type_
    except TypeError:
        BaseClass = object

    class MetaClass(_ValidationMeta, BaseClass.__class__):
        """Use the type_ meta and include base validation functionality."""

    return BaseClass, MetaClass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    try:
        return bases[0].__metaclass__
    except AttributeError:
        pass
    try:
        return globals()['__metaclass__']
    except KeyError:
        pass
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    bases = tuple(bases)
    if bases:
        metaclass = None
        for cls in bases:
            if isinstance(cls, type):
                mc = cls.__metaclass__
                if not mc and hasattr(cls, "__metaclass__"):
                    mc = cls.__metaclass__
                if metaclass is None:
                    metaclass = mc
                elif mc is not None and mc != metaclass:
                    raise TypeError("Bases have multiple metaclasses: {} and {}".format(metaclass, mc))
        return metaclass if metaclass is not None else type
    elif explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit_mc is not a type")
        return explicit_mc
    else:
        return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is None:
        try:
            for a in bases:
                if a is not None and hasattr(a, "__metaclass__"):
                    return a.__metaclass__
        except Exception:
            pass

    # Metaclass inference failed, return None
    return None

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        else:
            raise KeyError(key)
    val = self.get(key)
    self.delete(key)
    return val

