def popitem(self):
    # Find the key, value pair with the lowest frequency in the cache
    # and remove it from the cache
    try:
        # Sort the cache by frequency and find the item with frequency 1
        sorted_cache = sorted(self._cache.items(), key=lambda x: x[1], reverse=True)
        for key, value in sorted_cache:
            if value == 1:
                break
        # Remove the item from the cache and return it
        self._cache.pop(key)
        return key, value
    except KeyError, e:
        raise KeyError(str(e))

