def fromutc(self, dt):
    from dlkit.abstract_osid.calendaring.primitives import DateTime as abc_datetime
    if not isinstance(dt, abc_datetime):
        raise TypeError("dt must be a timezone-aware datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")
    if dt.tzinfo == _UTC:
        return dt
    else:
        # determine whether the datetime is ambiguous
        ambiguous = self._is_ambiguous_at_utc(dt)
        if ambiguous:
            # if the datetime is ambiguous, return the first occurrence
            return dt.tzinfo.fold.utcoffset(dt, isdst=None)
        else:
            # otherwise, return the current occurrence
            return dt.tzinfo.utcoffset(dt, isdst=None)

def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.

    """
    if isinstance(dt, datetime.datetime) and dt.tzinfo is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

def default_tzinfo(dt, tzinfo):
    if not dt.tzinfo:
        return tzinfo.localize(dt)
    return dt

