def process_text_links(text):
    # Initialize memoized_urls dictionary
    memoized_urls = {}

    # Function for converting potential URL references to links
    def memoized_to_url(m):
        # If URL is not in memoized_urls, add it.
        if m.group(0) not in memoized_urls:
            memoized_urls[m.group(0)] = to_url(m)
        return memoized_urls[m.group(0)]

    # Function for converting a URL or file reference to a link
    def to_url(m):
        if m.group(1):
            return m.group(0)  # If URL is not in memoized_urls, add it.
        path = m.group(0)

        if path.startswith('/'):
            path = os.path.relpath(path, buildroot)
        elif path.startswith('..'):
            return None  # Path is not located inside the buildroot, so it's definitely not a BUILD file.
        else:
            # Potential reference to a target in a BUILD file.
            putative_dir = path
            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                    FileSystemProjectTree(buildroot),
                    putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        # Check if path exists
        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

