    def maybe_add_link(url, text):
        if url:
            return '<a target="_blank" href="{}">{}</a>'.format(url, text)
        else:
            return text

def process_text_links(text):
    links = {}
    for match in _LINK_RE.finditer(text):
        url = match.group(0)
        if url not in links:
            links[url] = ""
        if len(links[url]) == 0:
            links[url] += '<a href="' + url + '"'
            if _is_http_link(url):
                links[url] += ' target="_blank"'
            links[url] += '>' + url + '</a>'
    return " ".join(links.values())

