def verify_relayable_signature(public_key, doc, signature):
    try:
        sig_algo = get_signature_algorithm(public_key, doc)
        sig_val = get_signature_value(doc)
        sig_digest = get_digest_algorithm(doc)
        signed_info = get_signed_info(doc, sig_algo, sig_val, sig_digest)
        key_info = get_key_info(doc, public_key)
