            key_info
        )
    except Exception as e:
        raise Exception("Invalid signature") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # first try JSON format
        webfinger = json.loads(document)
    except json.JSONDecodeError:
        # try XRD format
        try:
            xrd = etree.fromstring(document)
            xmlns = "http://docs.oasis-open.org/ns/xri/xrd-1.0"
            elements = xrd.findall(".//{" + xmlns + "}*")
            webfinger = {}
            for element in elements:
                name = element.tag.split("}")[1]
                if name == "Title":
                    name = "name"
                if name == "Link":
                    name = "aliases"
                    webfinger[name] = element.attrib.get("rel")
                else:
                    webfinger[name] = element.text
                for attr in element.attrib:
                    if attr.startswith("p-"):
                        webfinger[attr] = element.attrib[attr]
        except etree.XMLSyntaxError:
            # raise JSONDecodeError as it was originally
            raise json.JSONDecodeError(msg="Invalid JSON or XRD format", document=document)
    return webfinger

