        result["profile"] = handle
    except AttributeError:
        pass
    try:
        for link in webfinger.findall("//link[@rel='http://eu.tumblr.com/rdf']"):
            result["eu.tumblr.com/rdf"] = link.attrib["href"]
    except AttributeError:
        pass
    try:
        for link in webfinger.findall("//link[@rel='http://joindiaspora.com/rdf']"):
