        if not (arg.min_ is None or arg.max_ is None):
            raise ValueError("Either both minimum and maximum values should be provided or none of them should.")
        if arg.min_ is None and arg.max_ is None:
            continue
        if arg.min_ > arg.max_:
            raise ValueError("Maximum value should be greater than or equal to the minimum value.")
        if arg.min_ is not None and arg.value < arg.min_:
            raise ValueError("Value is less than the minimum value.")
        if arg.max_ is not None and arg.value > arg.max_:
            raise ValueError("Value is greater than the maximum value.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("Expected 'args' to be a dict, but got {}".format(type(args)))

    min_value = self.min_value
    max_value = self.max_value
    if min_value is None and max_value is None:
        raise ValueError("'min_value' and 'max_value' must be provided")
    if min_value is None:
        raise ValueError("'min_value' must be provided")
    if max_value is None:
        raise ValueError("'max_value' must be provided")

    for k, v in args.items():
        if min_value <= v <= max_value:
            return k, v
    raise ValueError("Found no value between 'min_value' and 'max_value' for key '{}'".format(k))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if not (arg.min <= arg.value <= arg.max):
            raise ValueError('Argument {0} must be between {1} and {2}'.format(arg.name, arg.min, arg.max))

def validate_min_max_args(self, args):
    if len(args) != 3:
        raise TypeError("Expected 3 arguments, got " + str(len(args)))

    if args[1] > args[2]:
        raise ValueError("The minimum argument should be less than or equal to the maximum argument")

    if args[0] < args[1] or args[0] > args[2]:
        raise ValueError("The argument should be between the minimum and maximum values")

    return args

def create_complex_arg_type(subcommand, type_name, option_name, spec_option):
    """Build the complex argument type."""
    # Validate input
    if subcommand is None:
        raise ValueError("'subcommand' must not be None.")
    if type_name is None:
        raise ValueError("'type_name' must not be None.")
    if option_name is None:
        raise ValueError("'option_name' must not be None.")
    if spec_option is None:
        raise ValueError("'spec_option' must not be None.")
    # Create a new argument type
    arg_type = self.proto.Types(name=type_name)
    # Add the option to the argument type
    arg_type.options.append(
        self.proto.Options(name=option_name, description=spec_option.description)
    )
    # Add the argument type to the command
    self.proto.Subcommands(
        namespace=subcommand, typename=type_name, documentation=spec_option.description
    )
    return arg_type

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.
    Controls arguments: control the IR behavior. These arguments
    will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.
    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.lstrip('-').startswith('extra-vars'):
            custom_args[arg] = args[arg]
        elif arg.lstrip('-').startswith('cmd_'):
            control_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom."""
    control_args = {}
    nested_args = {}
    custom_args = {}
    for k, v in args.items():
        if k in self.control_args:
            control_args[k] = v
        elif k in self.nested_args:
            nested_args[k] = v
        else:
            custom_args[k] = v
    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(args):
    control_args = {}
    nested_args = {}
    custom_args = {}
    for arg in args:
        if arg.startswith('-c '):
            control_arg = arg[2:]
            control_args[control_arg] = args[arg]
        elif arg.startswith('--custom '):
            custom_arg = arg[7:]
            custom_args[custom_arg] = args[arg]
        else:
            nested_arg = arg[2:]
            nested_args[nested_arg] = args[arg]
    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('control='):
            control_args[arg] = self._get_control_args(arg)
        elif arg.startswith('nested='):
            nested_args[arg] = self._get_nested_args(arg)
        elif arg.startswith('custom='):
            custom_args[arg] = self._get_custom_args(arg)

    return (control_args, nested_args, custom_args)

