def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra_vars``

        :param vars_dict: Dictionary to merge extra_vars into
        :param extra_vars: List of extra_vars
        """
        if extra_vars is None:
            return vars_dict

        for var_name, var_value in extra_vars:
            vars_dict[var_name] = var_value

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    if not isinstance(vars_dict, dict):
        raise ValueError("'vars_dict' must be a dictionary.")

    if not isinstance(extra_vars, list):
        raise ValueError("'extra_vars' must be a list.")

    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            vars_dict.update(extra_var)
        else:
            raise ValueError("'extra_vars' must be a list of dictionaries.")

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is not None and not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")
    if extra_vars is None:
        return vars_dict
    updated_vars = {}
    for var in vars_dict:
        if var in extra_vars:
            raise KeyError(f"Variable '{var}' already exists in vars_dict")
        updated_vars[var] = vars_dict[var]
    for var in extra_vars:
        updated_vars[var] = extra_vars[var]
    return updated_vars

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """

    # Validate input parameters
    if not ir_workspace or not ir_plugin or not playbook_path:
        raise ValueError("Missing required input parameters")

    # Set up environment variables
    ansible_extra_vars = {"plugin": plugin.name, "playbook_path": playbook_path}
    if extra_vars:
        ansible_extra_vars.update(extra_vars)

    # Build ansible-playbook command
    ansible_command = ["ansible-playbook", playbook_path]
    if verbose:
        ansible_command = ansible_command + ["-v", str(verbose)]
    if extra_vars:
        ansible_command = ansible_command + ["--extra-vars", json.dumps(ansible_extra_vars)]
    if ansible_args:
        ansible_command = ansible_command + ["--"] + ansible_args

    # Execute ansible-playbook command
    try:
        subprocess.check_output(ansible_command, stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Ansible reported an error when executing playbook %s: %s" % (playbook_path, e.stdout))

def _convert_non_cli_args(self, parser_name, values_dict):
    parser = argparse.ArgumentParser(prog=parser_name)

    for opt in self:
        if opt.name in values_dict:
            values_dict[opt.name] = opt.convert(values_dict[opt.name])
        elif opt.default is not None:
            values_dict[opt.name] = opt.convert(opt.default)

    return parser.parse_known_args(namespace=values_dict)[0]

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    argparse = argparse.ArgumentParser(prog=parser_name)

    for args in argparse._actions:
        if hasattr(args, 'type'):
            for name, value in values_dict.items():
                try:
                    values_dict[name] = args.type(value)
                except ValueError:
                    values_dict[name] = value

