def get_os_type(os_type_string):
    """Converts string representing OS type to an OS type enum.

    Raises an exception if the input string is not recognized.

    :param os_type_string: The string representing the OS type.
    :returns: The appropriate enum value of OS type.
    """
    OS_TYPE_MAP = {'Ubuntu': OS_TYPE.UBUNTU,
                  'CentOS': OS_TYPE.CENTOS,
                  'RHEL': OS_TYPE.RHEL,
                  'SUSE': OS_TYPE.SUSE}
    if os_type_string in OS_TYPE_MAP:
        return OS_TYPE_MAP[os_type_string]
    else:
        raise ValueError(f"Invalid OS type {os_type_string}")

