def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_dict = {}
    for plugin in os.listdir(plugin_dir):
        plugin_path = os.path.join(plugin_dir, plugin)
        if os.path.isfile(plugin_path) and os.path.splitext(plugin_path)[1] == '.yaml':
            with open(plugin_path) as f:
                plugin_dict[plugin] = yaml.safe_load(f)
    return plugin_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    logger.debug('Injecting config path as environment variable ...')

    if 'CONFIG_PATH' not in os.environ:
        logger.debug('No config path specified in environment variable')
        config_path = _find_config_path()

        if config_path is not None:
            logger.debug('Config path found: {}'.format(config_path))
            os.environ['CONFIG_PATH'] = config_path
        else:
            logger.warning('Config path not found, inject_config failed.')

    else:
        logger.debug('Config path already set in environment variable: {}'.format(os.environ['CONFIG_PATH']))

    return os.environ['CONFIG_PATH']

